"use client";
/**
 * Clio ring: progress toward a goal as a thin ring that fills once the tile has risen, with the count in the middle.
 */
import type { ReactNode } from "react";
import {
  ClioTile,
  type ClioTileProps,
  clioTileAliveDelay,
  useClioAlive,
  useClioCountUp,
} from "./theme";

const CSS = `
.clio-ring__body{flex:1;display:flex;align-items:center;justify-content:center;gap:14px;padding-top:8px;min-height:0}
.clio-ring__figure{position:relative;flex:none;width:var(--clio-ring-size);height:var(--clio-ring-size);margin:0}
.clio-ring__svg{display:block;width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.clio-ring__track{fill:none;stroke:var(--clio-track);transition:stroke var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-ring__arc{fill:none;stroke:var(--clio-accent);stroke-linecap:round;transition:stroke-dashoffset var(--clio-alive-ms) var(--clio-alive-ease),stroke var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-ring__ticks{stroke:var(--clio-hairline-strong);transition:stroke var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-ring__center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;text-align:center}
.clio-ring__value{font-size:var(--clio-ring-numeral)}
.clio-ring__detail{text-align:center}
.clio-ring[data-empty] .clio-ring__arc{opacity:0}
@media (prefers-reduced-motion:reduce){.clio-ring__arc{transition:stroke var(--clio-mode-ms) var(--clio-mode-ease)}}
`;

export interface ClioRingArc {
  /** The share filled, clamped to 0–100. */
  percent: number;
  circumference: number;
  /** stroke-dasharray for the arc. */
  dashArray: string;
  /** stroke-dashoffset for the arc: the circumference when empty, 0 when full. */
  dashOffset: number;
  /** Where the arc ends, in the circle's own coordinates (centre at 0,0, starting at 12 o'clock, clockwise). */
  end: { x: number; y: number };
}

/** The arc of a ring `percent` full (clamped to 0–100; anything not a number is 0), for a circle of `radius`. */
export function clioRingArc(percent: number, radius: number): ClioRingArc {
  const p = Number.isFinite(percent) ? Math.min(100, Math.max(0, percent)) : 0;
  const r = Math.max(0, radius);
  const circumference = 2 * Math.PI * r;
  const angle = (p / 100) * 2 * Math.PI;
  return {
    percent: p,
    circumference,
    dashArray: `${circumference} ${circumference}`,
    dashOffset: circumference * (1 - p / 100),
    end: { x: r * Math.sin(angle), y: -r * Math.cos(angle) },
  };
}

export interface ClioRingProps extends Omit<ClioTileProps, "children" | "label"> {
  label?: ReactNode;
  /** Done so far. */
  value: number;
  /** The goal. The ring shows value / max, clamped to the full ring. */
  max?: number;
  /** The caption under the count, e.g. "of 8". */
  of?: ReactNode;
  /** A line under the ring. */
  detail?: ReactNode;
  /** Ring diameter in px. */
  size?: number;
  /** Ring thickness in px. */
  thickness?: number;
  /** Twelve small ticks around the ring. */
  ticks?: boolean;
  /** Fill after the rise. Off, the ring shows full at once. */
  animate?: boolean;
  /** What screen readers hear, e.g. "5 of 8 read". */
  valueText?: string;
}

export function ClioRing({
  label = "Read this week",
  value,
  max = 100,
  of,
  detail,
  size = 112,
  thickness = 5,
  ticks = true,
  animate = true,
  valueText,
  riseIndex,
  riseDelay,
  className,
  ...tile
}: ClioRingProps) {
  const percent = max > 0 ? (value / max) * 100 : 0;
  const radius = (size - thickness) / 2 - (ticks ? 5 : 0);
  const arc = clioRingArc(percent, radius);
  const aliveDelay = clioTileAliveDelay(riseIndex, riseDelay);
  const alive = useClioAlive(aliveDelay, animate);
  const shown = useClioCountUp(value, { delay: aliveDelay, enabled: animate });
  const c = size / 2;
  const caption = of ?? `of ${max}`;
  return (
    <ClioTile
      {...tile}
      label={label}
      riseIndex={riseIndex}
      riseDelay={riseDelay}
      className={className ? `clio-ring ${className}` : "clio-ring"}
      data-empty={arc.percent === 0 ? "" : undefined}
      style={{
        ["--clio-ring-size" as string]: `${size}px`,
        ["--clio-ring-numeral" as string]: `${Math.round(size * 0.3)}px`,
        ...tile.style,
      }}
    >
      <style>{CSS}</style>
      <div className="clio-ring__body">
        <div
          className="clio-ring__figure"
          role="progressbar"
          aria-valuemin={0}
          aria-valuemax={max}
          aria-valuenow={Math.min(Math.max(0, value), max)}
          aria-valuetext={valueText ?? `${value} of ${max}`}
          aria-label={typeof label === "string" ? label : undefined}
        >
          <svg className="clio-ring__svg" viewBox={`0 0 ${size} ${size}`} aria-hidden="true">
            {ticks ? (
              <g className="clio-ring__ticks" strokeWidth="1" strokeLinecap="round">
                {Array.from({ length: 12 }, (_, i) => {
                  const a = (i / 12) * 2 * Math.PI;
                  const r1 = size / 2 - 1.5;
                  const r2 = size / 2 - 4;
                  return (
                    <line
                      key={i}
                      x1={c + r1 * Math.cos(a)}
                      y1={c + r1 * Math.sin(a)}
                      x2={c + r2 * Math.cos(a)}
                      y2={c + r2 * Math.sin(a)}
                    />
                  );
                })}
              </g>
            ) : null}
            <circle className="clio-ring__track" cx={c} cy={c} r={radius} strokeWidth={thickness} />
            <circle
              className="clio-ring__arc"
              cx={c}
              cy={c}
              r={radius}
              strokeWidth={thickness}
              strokeDasharray={arc.dashArray}
              strokeDashoffset={alive ? arc.dashOffset : arc.circumference}
            />
          </svg>
          <div className="clio-ring__center" aria-hidden="true">
            <span className="clio-numeral clio-ring__value">{shown}</span>
            <span className="clio-caption">{caption}</span>
          </div>
        </div>
      </div>
      {detail ? <p className="clio-caption clio-ring__detail">{detail}</p> : null}
    </ClioTile>
  );
}
